{
  "verses": [
    {
      "chapter": 10,
      "text_ar": "لِيَفْرَحِ الْقِدِّيسُونَ، وَلْتَبْتَهِجْ قُلُوبُهُمْ بِالْبَهْجَةِ، لِأَنَّهُمْ سَيَنْالُونَ الْمَجْدَ الْمُخَزَّنَ لَهُمْ.",
      "verse": 21
    },
    {
      "chapter": 10,
      "text_ar": "قَدْ غُفِرَتْ خَطَايَانَا، وَطُهِرَ إِثْمُنَا، أَمَّا أَلِيهُو فَلَيْسَ لَهُ ذِكْرٌ بَيْنَ الْأَحْيَاءِ.",
      "verse": 22
    },
    {
      "chapter": 10,
      "text_ar": "وَبَعْدَ أَنْ أَنْتَهَى أَلِيفَازُ مِنَ التَّسْبِحَةِ، قُمْنَا وَرَجَعْنَا إِلَى الْمَدِينَةِ، كُلُّ وَاحِدٍ إِلَى الْمَنْزِلِ الَّذِي كَانَ يَسْكُنُ فِيهِ.",
      "verse": 23
    },
    {
      "chapter": 10,
      "text_ar": "وَصَنَعَ لِيَ الشَّعْبُ وَلِيمَةً امْتِنَانًا وَبَهْجَةً لِلَّهِ، وَرَجَعَ إِلَيَّ جَمِيعُ أَصْدِقَائِي.",
      "verse": 24
    },
    {
      "chapter": 10,
      "text_ar": "وَجَمِيعُ الَّذِينَ رَأَوْنِي فِي حَالَةِ سَعَادَتِي السَّابِقَةِ، سَأَلُونِي قَائِلِينَ: «مَا هَذِهِ الْأُمُورُ الثَّلَاثَةُ هُنَا بَيْنَنَا»",
      "verse": 25
    }
  ],
  "book_code": "TJOB"
}
